using System;
using UnityEngine;

namespace Jagti.World
{
    /// <summary>
    /// Campus layout data loaded from Assets/Data/campus_layout.json.
    /// The JSON is generated by tools/layout/generate_layout.py from the 2D vision map.
    /// 1 unit = 1 metre; the origin is the central roundabout; map "up" is +Z.
    /// </summary>
    [Serializable]
    public class CampusLayout
    {
        public string info;
        public int version;      // bump in generate_layout.py to make Unity rebuild the scene
        public float floorHeight;
        public BuildingData[] buildings;
        public RoadData[] roads;
        public AreaData[] areas;
        public PlaceData[] places;
        public float[] boundary; // flat list: x0, z0, x1, z1, ...
        public RoadData[] water; // channels: same shape as roads
        public PoolData[] pools;
        public Point2 spawn;

        public static CampusLayout FromJson(string json)
        {
            return JsonUtility.FromJson<CampusLayout>(json);
        }
    }

    [Serializable]
    public class BuildingData
    {
        public string name;
        public string zone;
        public string shape; // "box" or "cylinder"
        public float x;
        public float z;
        public float width;
        public float depth;
        public float height;
        public int floors;
    }

    [Serializable]
    public class RoadData
    {
        public string name;
        public float width;
        public float[] points; // flat list: x0, z0, x1, z1, ...
    }

    [Serializable]
    public class AreaData
    {
        public string type;  // lawn, courtyard, parking, court, track, field, amphitheatre, roundabout, substation
        public string shape; // "box" or "ellipse"
        public float x;
        public float z;
        public float width;
        public float depth;
    }

    [Serializable]
    public class PoolData
    {
        public string name;
        public float x;
        public float z;
        public float radius;
    }

    [Serializable]
    public class PlaceData
    {
        public string name;
        public float x;
        public float z;
    }

    [Serializable]
    public class Point2
    {
        public float x;
        public float z;
    }
}
